export const HARDWARE_IMAGES: Record<string, string> = {
  "anakart": "",
  "islemci": "",
  "ram": "",
  "ssd": "",
  "gpu": "",
  "guc": "",
  "fan": "",
  "klavye": "",
  "fare": "",
  "tarayici": "",
  "mikrofon": "",
  "monitor": "",
  "yazici": "",
  "dokunmatik": "",
  "hoparlor": "",
  "kulaklik": "",
  "modem": ""
};

export const getHardwareImageSrc = (key: string): string => {
  const base64 = HARDWARE_IMAGES[key];
  if (!base64) return '';
  return `data:image/jpeg;base64,${base64}`;
};
